#!/usr/bin/env python3
import os, sys, re, hashlib, datetime, argparse, pathlib, calendar, tempfile

# Helpers for date parsing
def parse_input_date(s, fmt):
    s=s.strip()
    low=s.lower()
    today=datetime.date.today()
    if low in ("today","now"):
        return datetime.datetime.combine(today, datetime.time.min)
    if low=="tomorrow":
        return datetime.datetime.combine(today+datetime.timedelta(days=1), datetime.time.min)
    if low=="yesterday":
        return datetime.datetime.combine(today+datetime.timedelta(days=-1), datetime.time.min)
    weekdays={"mon":0,"monday":0,"tue":1,"tuesday":1,"wed":2,"wednesday":2,"thu":3,"thursday":3,"fri":4,"friday":4,"sat":5,"saturday":5,"sun":6,"sunday":6,
              "tues":1,"thurs":3,"thur":3}
    if low in weekdays:
        target=weekdays[low]
        cur=today.weekday()
        delta=(target-cur)%7
        return datetime.datetime.combine(today+datetime.timedelta(days=delta), datetime.time.min)
    # split time
    time_part=None
    date_part=s
    if " " in s:
        parts=s.rsplit(" ",1)
        if re.match(r'^\d{1,2}:\d{2}$', parts[1]):
            date_part=parts[0]
            time_part=parts[1]
    try:
        if fmt==1:
            m=re.match(r'^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$', date_part)
            if not m: raise ValueError
            month=int(m.group(1)); day=int(m.group(2)); year=int(m.group(3))
        elif fmt==2:
            m=re.match(r'^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$', date_part)
            if not m: raise ValueError
            day=int(m.group(1)); month=int(m.group(2)); year=int(m.group(3))
        elif fmt==3:
            m=re.match(r'^\s*(\d{4})/(\d{1,2})/(\d{1,2})\s*$', date_part)
            if not m: raise ValueError
            year=int(m.group(1)); month=int(m.group(2)); day=int(m.group(3))
        elif fmt==4:
            m=re.match(r'^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$', date_part)
            if not m: raise ValueError
            year=int(m.group(1)); month=int(m.group(2)); day=int(m.group(3))
        else:
            raise ValueError
        datetime.date(year,month,day)
    except Exception:
        raise ValueError(f"invalid date: {s}")
    if time_part:
        hh,mm=map(int,time_part.split(":"))
        return datetime.datetime(year,month,day,hh,mm)
    else:
        return datetime.datetime(year,month,day,0,0)

def parse_file_date(s):
    s=s.strip()
    m=re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})$', s)
    if not m:
        raise ValueError
    month=int(m.group(1)); day=int(m.group(2)); year=int(m.group(3))
    return datetime.date(year,month,day)

def parse_file_time(s):
    s=s.strip()
    m=re.match(r'^(\d{2}):(\d{2})$', s)
    if not m:
        raise ValueError
    return int(m.group(1)), int(m.group(2))

def days_in_month(y,m):
    return calendar.monthrange(y,m)[1]

def first_weekday_of_month(y,m,wd):
    # wd: SU=0, MO=1,...
    py_map={0:6,1:0,2:1,3:2,4:3,5:4,6:5}
    py_wd=py_map[wd]
    d=datetime.date(y,m,1)
    delta=(py_wd - d.weekday())%7
    return d+datetime.timedelta(days=delta)

def nth_weekday_of_month(y,m,n,wd):
    if n>0:
        first=first_weekday_of_month(y,m,wd)
        cand=first+datetime.timedelta(weeks=n-1)
        if cand.month!=m:
            return None
        return cand
    else:
        dim=days_in_month(y,m)
        last=datetime.date(y,m,dim)
        py_map={0:6,1:0,2:1,3:2,4:3,5:4,6:5}
        py_wd=py_map[wd]
        delta=(last.weekday() - py_wd)%7
        last_occ=last - datetime.timedelta(days=delta)
        cand=last_occ + datetime.timedelta(weeks=n+1)
        if cand.month!=m:
            return None
        return cand

class Recurrence:
    def __init__(self):
        self.interval=1
        self.freq_type='D'
        self.until=None
        self.exceptions=[]
        self.byday=[]
        self.bymonth=[]
        self.bymonthday=[]
    @staticmethod
    def parse(s):
        rec=Recurrence()
        tokens=s.strip().split()
        if not tokens:
            return None
        m=re.match(r'^(\d+)([DWMY])$', tokens[0])
        if not m:
            raise ValueError("invalid freq")
        rec.interval=int(m.group(1))
        rec.freq_type=m.group(2)
        idx=1
        if idx<len(tokens) and tokens[idx]=="->":
            idx+=1
            if idx<len(tokens):
                rec.until=parse_file_date(tokens[idx])
                idx+=1
        while idx<len(tokens):
            tok=tokens[idx]
            if tok.startswith("!"):
                rec.exceptions.append(parse_file_date(tok[1:]))
            elif tok.startswith("w"):
                try:
                    w_val=int(tok[1:])
                except:
                    raise ValueError("invalid w")
                if w_val>=0:
                    occ=w_val//7
                    wd=w_val%7
                else:
                    aw=-w_val
                    occ= - (aw//7)
                    wd=aw%7
                rec.byday.append((occ,wd))
            elif tok.startswith("m"):
                try:
                    rec.bymonth.append(int(tok[1:]))
                except:
                    raise ValueError("invalid m")
            elif tok.startswith("d"):
                try:
                    rec.bymonthday.append(int(tok[1:]))
                except:
                    raise ValueError("invalid d")
            else:
                raise ValueError("invalid token")
            idx+=1
        return rec
    def to_string(self):
        parts=[f"{self.interval}{self.freq_type}"]
        if self.until:
            parts.append("->")
            parts.append(self.until.strftime("%m/%d/%Y"))
        for d in sorted(self.bymonthday):
            parts.append(f"d{d}")
        w_vals=[]
        for occ,wd in self.byday:
            if occ==0:
                w_vals.append(wd)
            elif occ>0:
                w_vals.append(occ*7+wd)
            else:
                w_vals.append(occ*7-wd)
        for w in sorted(w_vals):
            parts.append(f"w{w}")
        for m in sorted(self.bymonth):
            parts.append(f"m{m}")
        for ex in sorted(self.exceptions):
            parts.append(f"!{ex.strftime('%m/%d/%Y')}")
        return " ".join(parts)

class CalItem:
    def __init__(self,start,end,desc,note_hash=None,rec=None,raw=None):
        self.start=start
        self.end=end
        self.desc=desc
        self.note_hash=note_hash
        self.rec=rec
        self.raw=raw
    def is_appt(self):
        return isinstance(self.start, datetime.datetime)
    def is_event(self):
        return isinstance(self.start, datetime.date) and not isinstance(self.start, datetime.datetime)
    def dur_sec(self):
        if self.is_appt() and isinstance(self.end, datetime.datetime):
            return int((self.end-self.start).total_seconds())
        return 0
    def hash_raw(self):
        if not self.raw:
            return ""
        return hashlib.sha1(self.raw.encode('utf-8')).hexdigest()

class TodoItem:
    def __init__(self,prio,desc,note_hash=None,completed=False,raw=None):
        self.prio=prio
        self.desc=desc
        self.note_hash=note_hash
        self.completed=completed
        self.raw=raw
    def hash_raw(self):
        if not self.raw:
            return ""
        return hashlib.sha1(self.raw.encode('utf-8')).hexdigest()

def parse_apts(path):
    items=[]
    try:
        with open(path,'r',encoding='utf-8',errors='ignore') as f:
            lines=f.readlines()
    except FileNotFoundError:
        return items
