                sdt=datetime.datetime(sd.year,sd.month,sd.day,st_h,st_m)
                edt=datetime.datetime(ed.year,ed.month,ed.day,et_h,et_m)
            except:
                print(f"io.c: 543: {path}:{idx}: syntax error in item state", file=sys.stderr)
