def generate_occurrences(rec,start_date,from_date,to_date):
    occs=[]
    until=rec.until if rec.until else datetime.date(2100,1,1)
    if not rec.byday and not rec.bymonth and not rec.bymonthday:
        if rec.freq_type=='D':
            cur=start_date
            if cur<from_date:
                delta=(from_date-cur).days
                steps=(delta+rec.interval-1)//rec.interval
                cur=cur+datetime.timedelta(days=steps*rec.interval)
            while cur<=to_date and cur<=until:
                if cur not in rec.exceptions:
                    occs.append(cur)
                cur+=datetime.timedelta(days=rec.interval)
        elif rec.freq_type=='W':
            cur=start_date
            if cur<from_date:
                # advance to from_date's week?
                # simple: iterate weeks
                delta=(from_date-cur).days
                weeks=delta//7
                steps=(weeks+rec.interval-1)//rec.interval
                cur=cur+datetime.timedelta(weeks=steps*rec.interval)
            while cur<=to_date and cur<=until:
                if cur not in rec.exceptions:
                    occs.append(cur)
                cur+=datetime.timedelta(weeks=rec.interval)
        elif rec.freq_type=='M':
            def add_months(y,m,d):
                total=y*12+(m-1)+d
                return total//12,total%12+1
            y,m=start_date.year,start_date.month
            day=start_date.day
            while True:
                try:
                    dim=days_in_month(y,m)
                    if day<=dim:
                        cand=datetime.date(y,m,day)
                        if cand>until or cand>to_date:
                            break
                        if cand>=from_date and cand not in rec.exceptions:
                            occs.append(cand)
                except:
                    pass
                y,m=add_months(y,m,rec.interval)
                if y>2100:
                    break
                if datetime.date(y,m,1)>until and y>until.year:
                    break
        elif rec.freq_type=='Y':
            y=start_date.year
            while y<=to_date.year and y<=until.year:
                try:
                    cand=datetime.date(y,start_date.month,start_date.day)
