        def parse_ical_duration_simple(dur_str):
            if not dur_str.startswith("P"):
                raise ValueError
            ds=dur_str[1:]
            days=0
            hours=0
            mins=0
            secs=0
            if "T" in ds:
                date_part,time_part=ds.split("T",1)
            else:
                date_part=ds
                time_part=""
            m=re.search(r'(\d+)D', date_part)
            if m:
                days+=int(m.group(1))
            m=re.search(r'(\d+)W', date_part)
            if m:
                days+=int(m.group(1))*7
            m=re.search(r'(\d+)H', time_part)
            if m:
                hours=int(m.group(1))
            m=re.search(r'(\d+)M', time_part)
            if m:
                mins=int(m.group(1))
            m=re.search(r'(\d+)S', time_part)
            if m:
                secs=int(m.group(1))
            return datetime.timedelta(days=days,hours=hours,minutes=mins,seconds=secs)

        def parse_ical_dt_for_import(dt_str,params):
            if params and "VALUE=DATE" in params:
                try:
                    y=int(dt_str[0:4]); m=int(dt_str[4:6]); d=int(dt_str[6:8])
                    return datetime.date(y,m,d)
                except:
                    raise ValueError
            # Remove Z
            ds=dt_str.rstrip('Z')
            if 'T' in ds:
                try:
                    dp,tp=ds.split('T')
                    y=int(dp[0:4]); mo=int(dp[4:6]); d=int(dp[6:8])
                    h=int(tp[0:2]); mi=int(tp[2:4]); se=int(tp[4:6]) if len(tp)>=6 else 0
                    return datetime.datetime(y,mo,d,h,mi,se)
                except:
                    raise ValueError
            else:
                try:
                    y=int(ds[0:4]); mo=int(ds[4:6]); d=int(ds[6:8])
                    return datetime.date(y,mo,d)
                except:
                    raise ValueError

        def ical_unescape_simple(s):
            res=""
            i=0
            while i < len(s):
                if s[i]=='\\' and i+1<len(s):
                    nxt=s[i+1]
                    if nxt in ('n','N'):
                        res+="\n"
                        i+=2
                    elif nxt==',':
                        res+=","
                        i+=2
                    elif nxt==';':
                        res+=";"
                        i+=2
                    elif nxt=='\\':
                        res+="\\"
                        i+=2
                    else:
                        res+=nxt
                        i+=2
                else:
                    res+=s[i]
                    i+=1
            return res

        def ical_escape_simple(s):
            if s is None:
                return ""
            s=s.replace("\\","\\\\")
            s=s.replace(";","\\;")
            s=s.replace(",","\\,")
            s=s.replace("\n","\\n")
            return s

        def ical_escape_text_simple(s):
            if s is None:
                return ""
            if s.endswith("\n"):
                s=s[:-1]
            s=s.replace("\\","\\\\")
            s=s.replace(";","\\;")
            s=s.replace(",","\\,")
            s=s.replace("\n","\\n")
            return s

