            else:
                date_part=ds
                time_part=""
            m=re.search(r'(\d+)D', date_part)
            if m:
                days+=int(m.group(1))
            m=re.search(r'(\d+)W', date_part)
            if m:
                days+=int(m.group(1))*7
            m=re.search(r'(\d+)H', time_part)
            if m:
                hours=int(m.group(1))
            m=re.search(r'(\d+)M', time_part)
            if m:
                mins=int(m.group(1))
            m=re.search(r'(\d+)S', time_part)
            if m:
                secs=int(m.group(1))
            return datetime.timedelta(days=days,hours=hours,minutes=mins,seconds=secs)

