        elif rec.freq_type=='M':
            def add_months(y,m,d):
                total=y*12+(m-1)+d
                return total//12,total%12+1
            y,m=start_date.year,start_date.month
            while True:
                first=datetime.date(y,m,1)
                if first>to_date and (rec.until is None or first>rec.until):
                    if y>to_date.year+1:
                        break
