    def matches_hash(item):
        if not filter_hash:
            return True
        neg=False
        h=filter_hash
        if h.startswith("!"):
            neg=True
            h=h[1:]
        ih=item.hash_raw()
        if not ih:
            return False if not neg else True
        starts=ih.lower().startswith(h.lower())
        return not starts if neg else starts

    filtered_apts=[]
    filtered_todo=[]

    for it in apts_items:
