                edt=datetime.datetime(it.start.year,it.start.month,it.start.day,23,59,59)
                if f_start_from and sdt < f_start_from:
                    match=False
                if f_start_to and sdt > f_start_to:
                    match=False
                if f_start_after and sdt <= f_start_after:
                    match=False
                if f_start_before and sdt >= f_start_before:
                    match=False
                if fsr_f and fsr_t:
                    if not (fsr_f <= sdt <= fsr_t):
                        match=False
                if f_end_from and edt < f_end_from:
                    match=False
                if f_end_to and edt > f_end_to:
                    match=False
                if f_end_after and edt <= f_end_after:
                    match=False
                if f_end_before and edt >= f_end_before:
                    match=False
                if fer_f and fer_t:
                    if not (fer_f <= edt <= fer_t):
                        match=False
        if filter_invert:
            match=not match
        if match:
            filtered_apts.append(it)

    for it in todo_items:
        match=True
        if "todo" not in type_set:
            match=False
        if match and pat_re:
            if not pat_re.search(it.desc):
                match=False
        if match and filter_hash:
            if not matches_hash(it):
                match=False
        if match and filter_priority:
            try:
                pri=int(filter_priority)
                if pri<1 or pri>9:
                    print(f"args.c: 783: invalid priority: {filter_priority}", file=sys.stderr); sys.exit(1)
                if it.prio!=pri:
                    match=False
            except ValueError:
                print(f"args.c: 783: invalid priority: {filter_priority}", file=sys.stderr); sys.exit(1)
        if match and filter_completed:
            if not it.completed:
                match=False
        if match and filter_uncompleted:
            if it.completed:
                match=False
        if filter_invert:
