                if rec.byday:
                    wd_map={0:"SU",1:"MO",2:"TU",3:"WE",4:"TH",5:"FR",6:"SA"}
                    b=[]
                    for occ,wd in rec.byday:
                        wd_s=wd_map.get(wd,"MO")
                        if occ==0:
