        except Exception as e:
            print(f"args.c: 797: invalid date: {from_date_str if f_date is None else to_date_str}", file=sys.stderr)
            sys.exit(1)
        days_num=None
        if days_str is not None:
            try:
                days_num=int(days_str)
            except:
                print(f"args.c: 797: invalid date: {days_str}", file=sys.stderr)
                sys.exit(1)
        if days_str is not None and to_date_str is not None:
            print("args.c: 880: invalid argument combination", file=sys.stderr)
            sys.exit(1)
        if f_date and t_date:
            return f_date, t_date
        elif f_date and days_num is not None:
            if days_num>=0:
                t_date=f_date+datetime.timedelta(days=days_num-1) if days_num!=0 else f_date
            else:
                t_date=f_date
                f_date=f_date+datetime.timedelta(days=days_num+1)
            return f_date, t_date
        elif f_date:
            return f_date, f_date
        elif t_date:
            return today, t_date
        elif days_num is not None:
            if days_num>=0:
                return today, today+datetime.timedelta(days=days_num-1) if days_num!=0 else today
            else:
                return today+datetime.timedelta(days=days_num+1), today
        else:
            return today, today

