                    v=props['PRIORITY']
                    if isinstance(v,list):
                        v=v[0]
                    _, val=v
                    try:
                        pv=int(val)
                        if pv<0 or pv>9:
                            raise Skip("invalid prio")
                        prio=pv
                    except:
                        raise Skip("invalid prio")
                if 'STATUS' in props:
                    v=props['STATUS']
                    if isinstance(v,list):
                        v=v[0]
                    _, val=v
                    if val.upper()=="COMPLETED":
                        comp=True
                note_c=None
                if desc_text is not None or loc_text is not None or comment_text is not None:
                    c=""
                    if desc_text is not None:
                        c+=desc_text+"\n"
                    if loc_text is not None or comment_text is not None:
                        c+="-- \n"
                        if loc_text is not None:
                            c+=f"Location: {loc_text}\n"
                        if comment_text is not None:
                            clines=comment_text.split("\n")
                            c+=f"Comment: {clines[0]}\n"
                            for cl in clines[1:]:
                                c+=f"    {cl}\n"
                    note_c=c
                return {'priority':prio,'description':summary,'note_content':note_c,'completed':comp}

        for line in unfolded:
            line=line.strip()
            if not line:
                continue
            if line=="BEGIN:VEVENT":
                cur_type="VEVENT"; props={}
            elif line=="BEGIN:VTODO":
                cur_type="VTODO"; props={}
            elif line=="END:VEVENT" or line=="END:VTODO":
                try:
                    info=process_item(cur_type,props)
                    if cur_type=="VEVENT":
                        if info['is_event']:
                            evts+=1
                        else:
                            apps+=1
                        new_apts_info.append(info)
                    else:
                        todos_cnt+=1
                        new_todos_info.append(info)
                except Skip:
                    skipped+=1
                except Exception:
                    skipped+=1
                cur_type=None; props={}
            else:
                if ':' not in line:
                    props['_malformed']=True
                    continue
                name_part, value=line.split(':',1)
                if ';' in name_part:
                    name,param_str=name_part.split(';',1)
                    params=param_str.split(';')
                else:
                    name=name_part; params=[]
                name=name.upper()
                if name in props:
                    if isinstance(props[name],list):
                        props[name].append((params,value))
                    else:
                        props[name]=[props[name],(params,value)]
                else:
                    props[name]=(params,value)

        # write

        apts_path=os.path.join(actual_data_dir,"apts")
        todo_path=os.path.join(actual_data_dir,"todo")
