        if not os.path.exists(apts_path):
            open(apts_path,'w').close()
        if not os.path.exists(todo_path):
            open(todo_path,'w').close()

        for info in new_apts_info:
            note_hash=None
            if info.get('note_content') is not None:
                nc=info['note_content']
                nh=hashlib.sha1(nc.encode('utf-8')).hexdigest()
                note_hash=nh
                fp=os.path.join(notes_dir_path,nh)
                if not os.path.exists(fp):
                    with open(fp,'w',encoding='utf-8') as nf:
                        nf.write(nc)
            if info['is_event']:
                sd=info['start']
                if isinstance(sd, datetime.datetime):
                    sd=sd.date()
                base=f"{sd.strftime('%m/%d/%Y')} [1]"
                if info.get('recurrence'):
                    base+=f" {{{info['recurrence'].to_string()}}}"
                if note_hash:
                    base+=f" >{note_hash}"
                if info['description']:
                    base+=f" {info['description']}"
                with open(apts_path,'a',encoding='utf-8') as af:
                    af.write(base+"\n")
                if dump_imported:
                    ci=CalItem(sd,None,info['description'],note_hash=note_hash,rec=info.get('recurrence'),raw=base)
                    fmt = format_event if not info.get('recurrence') else format_recur_event
                    if fmt is None:
                        fmt="%(raw)"
                    print(apply_format(fmt,ci,data_dir=actual_data_dir))
            else:
                sd=info['start']; ed=info['end']
                if not isinstance(sd, datetime.datetime):
                    sd=datetime.datetime(sd.year,sd.month,sd.day,0,0)
                if not isinstance(ed, datetime.datetime):
                    ed=datetime.datetime(ed.year,ed.month,ed.day,0,0)
                base=f"{sd.strftime('%m/%d/%Y')} @ {sd.strftime('%H:%M')} -> {ed.strftime('%m/%d/%Y')} @ {ed.strftime('%H:%M')}"
                if info.get('recurrence'):
                    base+=f" {{{info['recurrence'].to_string()}}}"
                if note_hash:
                    base+=f" >{note_hash} |"
                else:
                    base+=f"|"
                base+=info['description']
                with open(apts_path,'a',encoding='utf-8') as af:
                    af.write(base+"\n")
                if dump_imported:
                    ci=CalItem(sd,ed,info['description'],note_hash=note_hash,rec=info.get('recurrence'),raw=base)
                    fmt = format_apt if not info.get('recurrence') else format_recur_apt
                    if fmt is None:
                        fmt="%(raw)"
                    print(apply_format(fmt,ci,data_dir=actual_data_dir))

        for info in new_todos_info:
            note_hash=None
            if info.get('note_content') is not None:
                nc=info['note_content']
                nh=hashlib.sha1(nc.encode('utf-8')).hexdigest()
                note_hash=nh
                fp=os.path.join(notes_dir_path,nh)
                if not os.path.exists(fp):
                    with open(fp,'w',encoding='utf-8') as nf:
                        nf.write(nc)
            if info['completed']:
                base="[-0]"
            else:
                base=f"[{info['priority']}]"
            if note_hash:
                base+=f">{note_hash} "
            base+=info['description']
            with open(todo_path,'a',encoding='utf-8') as tf:
                tf.write(base+"\n")
            if dump_imported:
                ti=TodoItem(info['priority'],info['description'],note_hash=note_hash,completed=info['completed'],raw=base)
                fmt=format_todo
                if fmt is None:
                    fmt="%(raw)"
                print(apply_format(fmt,ti,data_dir=actual_data_dir))

        if not quiet:
            # need correct plural handling
            app_str = f"{apps} app{'s' if apps!=1 else ''}"
            evt_str = f"{evts} event{'s' if evts!=1 else ''}"
            todo_str = f"{todos_cnt} todo{'s' if todos_cnt!=1 else ''}"
            print(f"Import process report: {lines_read:04d} lines read")
            print(f"{app_str} / {evt_str} / {todo_str} / {skipped} skipped")
            if skipped>0:
