    # Load items
    apts_items=parse_apts(calendar_file_path)
    todo_items=parse_todo(todo_path_actual)

    # Filter helper
    def parse_filter_date_opt(val):
        if val is None:
            return None
        try:
            return parse_input_date(val, input_datefmt)
        except:
            print(f"args.c: 797: invalid date: {val}", file=sys.stderr); sys.exit(1)

    f_start_from=parse_filter_date_opt(filter_start_from)
    f_start_to=parse_filter_date_opt(filter_start_to)
    f_start_after=parse_filter_date_opt(filter_start_after)
    f_start_before=parse_filter_date_opt(filter_start_before)
    f_end_from=parse_filter_date_opt(filter_end_from)
    f_end_to=parse_filter_date_opt(filter_end_to)
    f_end_after=parse_filter_date_opt(filter_end_after)
    f_end_before=parse_filter_date_opt(filter_end_before)

    def parse_range_str(rs):
        if not rs:
            return None,None
        parts=rs.split(",")
        if len(parts)!=2:
            return None,None
        try:
            s=parse_input_date(parts[0].strip(), input_datefmt)
            e=parse_input_date(parts[1].strip(), input_datefmt)
            return s,e
        except:
            print(f"args.c: 797: invalid date: {rs}", file=sys.stderr); sys.exit(1)

    fsr_f=fsr_t=None
    if filter_start_range:
        fsr_f,fsr_t=parse_range_str(filter_start_range)
    fer_f=fer_t=None
    if filter_end_range:
        fer_f,fer_t=parse_range_str(filter_end_range)

    def count_non_none(lst):
        return sum(1 for x in lst if x)
    if count_non_none([filter_start_from, filter_start_after, filter_start_range])>1:
        print("args.c: 647: invalid filter mask", file=sys.stderr); sys.exit(1)
    if count_non_none([filter_start_to, filter_start_before, filter_start_range])>1:
        print("args.c: 647: invalid filter mask", file=sys.stderr); sys.exit(1)
    if count_non_none([filter_end_from, filter_end_after, filter_end_range])>1:
        print("args.c: 647: invalid filter mask", file=sys.stderr); sys.exit(1)
    if count_non_none([filter_end_to, filter_end_before, filter_end_range])>1:
        print("args.c: 647: invalid filter mask", file=sys.stderr); sys.exit(1)

    type_set=set()
    if filter_type:
        for tt in filter_type.split(","):
            tt=tt.strip()
            if tt=="event":
                type_set.add("event")
            elif tt=="apt":
                type_set.add("apt")
            elif tt=="recur-event":
                type_set.add("recur-event")
            elif tt=="recur-apt":
                type_set.add("recur-apt")
            elif tt=="recur":
                type_set.update(["recur-event","recur-apt"])
            elif tt=="cal":
                type_set.update(["event","apt","recur-event","recur-apt"])
            elif tt=="todo":
                type_set.add("todo")
            else:
                print("args.c: 647: invalid filter mask", file=sys.stderr); sys.exit(1)
    else:
        type_set.update(["event","apt","recur-event","recur-apt","todo"])

