    def matches_hash(item):
        if not filter_hash:
            return True
        neg=False
        h=filter_hash
        if h.startswith("!"):
            neg=True
            h=h[1:]
        ih=item.hash_raw()
        if not ih:
            return False if not neg else True
        starts=ih.lower().startswith(h.lower())
        return not starts if neg else starts

    filtered_apts=[]
    filtered_todo=[]

    for it in apts_items:
        is_recur=it.rec is not None
        if it.is_event():
            t="recur-event" if is_recur else "event"
        else:
            t="recur-apt" if is_recur else "apt"
        match=True
        if t not in type_set:
            match=False
        if match and pat_re:
            if not pat_re.search(it.desc):
                match=False
        if match and filter_hash:
            if not matches_hash(it):
                match=False
        if match:
            if it.is_appt():
                sdt=it.start
                edt=it.end if isinstance(it.end, datetime.datetime) else sdt
                if f_start_from and sdt < f_start_from:
                    match=False
                if f_start_to and sdt > f_start_to:
                    match=False
                if f_start_after and sdt <= f_start_after:
                    match=False
                if f_start_before and sdt >= f_start_before:
                    match=False
                if fsr_f and fsr_t:
                    if not (fsr_f <= sdt <= fsr_t):
                        match=False
                if f_end_from and edt < f_end_from:
                    match=False
                if f_end_to and edt > f_end_to:
                    match=False
                if f_end_after and edt <= f_end_after:
                    match=False
                if f_end_before and edt >= f_end_before:
                    match=False
                if fer_f and fer_t:
                    if not (fer_f <= edt <= fer_t):
                        match=False
            else:
                sdt=datetime.datetime(it.start.year,it.start.month,it.start.day,0,0)
                edt=datetime.datetime(it.start.year,it.start.month,it.start.day,23,59,59)
                if f_start_from and sdt < f_start_from:
                    match=False
                if f_start_to and sdt > f_start_to:
                    match=False
                if f_start_after and sdt <= f_start_after:
                    match=False
                if f_start_before and sdt >= f_start_before:
                    match=False
                if fsr_f and fsr_t:
                    if not (fsr_f <= sdt <= fsr_t):
                        match=False
                if f_end_from and edt < f_end_from:
                    match=False
                if f_end_to and edt > f_end_to:
                    match=False
                if f_end_after and edt <= f_end_after:
                    match=False
                if f_end_before and edt >= f_end_before:
                    match=False
                if fer_f and fer_t:
                    if not (fer_f <= edt <= fer_t):
                        match=False
        if filter_invert:
            match=not match
        if match:
            filtered_apts.append(it)

    for it in todo_items:
        match=True
        if "todo" not in type_set:
            match=False
        if match and pat_re:
            if not pat_re.search(it.desc):
                match=False
        if match and filter_hash:
            if not matches_hash(it):
                match=False
        if match and filter_priority:
            try:
                pri=int(filter_priority)
                if pri<1 or pri>9:
                    print(f"args.c: 783: invalid priority: {filter_priority}", file=sys.stderr); sys.exit(1)
                if it.prio!=pri:
                    match=False
            except ValueError:
                print(f"args.c: 783: invalid priority: {filter_priority}", file=sys.stderr); sys.exit(1)
        if match and filter_completed:
            if not it.completed:
                match=False
        if match and filter_uncompleted:
            if it.completed:
                match=False
        if filter_invert:
            match=not match
        if match:
            filtered_todo.append(it)

    if mode=="grep":
        for it in filtered_apts:
            is_recur=it.rec is not None
