        sys.exit(0)

    if mode=="export":
        fmt=export_format if export_format else "ical"
        if fmt=="ical":
            def rec_to_rrule(rec,start):
                freq_map={'D':'DAILY','W':'WEEKLY','M':'MONTHLY','Y':'YEARLY'}
                f=freq_map.get(rec.freq_type,'DAILY')
                parts=[f"FREQ={f}"]
                if rec.interval!=1:
                    parts.append(f"INTERVAL={rec.interval}")
                if rec.until:
                    if isinstance(start, datetime.datetime):
                        ud=datetime.datetime(rec.until.year,rec.until.month,rec.until.day, start.hour, start.minute, start.second)
                        parts.append(f"UNTIL={ud.strftime('%Y%m%dT%H%M%S')}")
                    else:
                        parts.append(f"UNTIL={rec.until.strftime('%Y%m%d')}")
                if rec.byday:
                    wd_map={0:"SU",1:"MO",2:"TU",3:"WE",4:"TH",5:"FR",6:"SA"}
                    b=[]
                    for occ,wd in rec.byday:
                        wd_s=wd_map.get(wd,"MO")
                        if occ==0:
                            b.append(wd_s)
                        else:
                            if occ>0:
                                b.append(f"+{occ}{wd_s}")
                            else:
                                b.append(f"{occ}{wd_s}")
                    parts.append(f"BYDAY={','.join(b)}")
                if rec.bymonth:
                    parts.append(f"BYMONTH={','.join(str(m) for m in rec.bymonth)}")
                if rec.bymonthday:
                    parts.append(f"BYMONTHDAY={','.join(str(d) for d in rec.bymonthday)}")
                return ";".join(parts)
            lines=[]
            lines.append("BEGIN:VCALENDAR")
