                sd=it.start
                lines.append(f"DTSTART;VALUE=DATE:{sd.strftime('%Y%m%d')}")
                if it.rec:
                    rr=rec_to_rrule(it.rec, sd)
                    if rr:
                        lines.append(f"RRULE:{rr}")
                    if it.rec.exceptions:
                        ex=[ex.strftime('%Y%m%d') for ex in it.rec.exceptions]
                        if ex:
                            lines.append(f"EXDATE;VALUE=DATE:{','.join(ex)}")
                lines.append(f"SUMMARY:{it.desc.replace(chr(10),'').replace(',','\\,').replace(';','\\;')}")
                if it.note_hash:
                    np=os.path.join(actual_data_dir,"notes",it.note_hash)
                    try:
                        with open(np,'r',encoding='utf-8',errors='ignore') as nf:
                            content=nf.read()
                            parts=content.split("\n-- \n")
                            dp=parts[0]
                            if dp.strip()!="":
                                if dp.endswith("\n"):
                                    dp=dp[:-1]
                                lines.append(f"DESCRIPTION:{dp.replace(chr(10),'\\n').replace(',','\\,').replace(';','\\;')}")
                            for sec in parts[1:]:
                                if sec.startswith("Location:"):
                                    loc=sec[len("Location:"):].strip()
                                    lines.append(f"LOCATION:{loc.replace(chr(10),'\\n').replace(',','\\,').replace(';','\\;')}")
                    except:
