                    r%=3600
                    m=r//60
                    s=r%60
                    lines.append(f"DURATION:P{d}DT{h}H{m}M{s}S")
                if it.rec:
                    rr=rec_to_rrule(it.rec, sd)
                    if rr:
                        lines.append(f"RRULE:{rr}")
                    if it.rec.exceptions:
                        ex=[]
                        for exd in it.rec.exceptions:
                            ex_dt=datetime.datetime(exd.year,exd.month,exd.day, sd.hour, sd.minute, sd.second)
                            ex.append(ex_dt.strftime('%Y%m%dT%H%M%S'))
                        if ex:
                            lines.append(f"EXDATE:{','.join(ex)}")
                lines.append(f"SUMMARY:{it.desc.replace(chr(10),'').replace(',','\\,').replace(';','\\;')}")
                if it.note_hash:
                    np=os.path.join(actual_data_dir,"notes",it.note_hash)
                    try:
                        with open(np,'r',encoding='utf-8',errors='ignore') as nf:
                            content=nf.read()
