                            for sec in parts[1:]:
                                if sec.startswith("Location:"):
                                    loc=sec[len("Location:"):].strip()
                                    lines.append(f"LOCATION:{loc.replace(chr(10),'\\n').replace(',','\\,').replace(';','\\;')}")
                    except:
                        pass
                if export_uid:
                    lines.append(f"UID:{it.hash_raw()}")
                lines.append("END:VEVENT")
            for it in filtered_todo:
